import pixeltable as pxt
from pixeltable.type_system import IntType, StringType, FloatType

pxt.init()

pxt.create_dir('demo')

table = pxt.create_table(
    'demo.films',
    schema={
        'title': StringType(),
        'year': IntType(),
        'revenue': FloatType()
    }
)

table.insert([
    {'title': 'Jaws', 'year': 1975, 'revenue': 470.7},
    {'title': 'Alien', 'year': 1979, 'revenue': 184.7}
])
